let TB_PICK=null,TB=null;
RENDER.teach=function(){const el=$('v-teach');S.teach=S.teach||{};
 if(!TB){const pool=TB_PICK?TEACH.filter(t=>t.c===TB_PICK):TEACH;const now=Date.now();const due=pool.filter(t=>!S.teach[t.c]||S.teach[t.c].due<=now);const item=(due.length?due:pool)[Math.floor(Math.random()*(due.length?due:pool).length)];TB={item,stage:'write',text:'',ticks:{}};TB_PICK=null;}
 const t=TB.item,node=WEB_NODES.find(n=>n[0]===t.c);
 if(TB.stage==='write'){el.innerHTML='<div class="view-head"><div class="ph"><span class="eyebrow">Teach it back · '+esc(node?node[1]:'')+'</span><h1>Explain it</h1></div><button class="btn small" id="tbSkip">Another prompt</button></div><div class="card" style="display:flex;flex-direction:column;gap:12px"><h2>'+esc(t.q)+'</h2><p class="note">Write it the way you would say it. Two to five sentences, no looking anything up: the point is to find the gaps.</p><textarea id="tbText" class="tb-text" rows="6" placeholder="Start with the one idea that matters most…">'+esc(TB.text)+'</textarea><div class="btnrow"><button class="btn primary" id="tbDone">I\'ve explained it</button><span class="note">Then grade yourself against the key points.</span></div></div>';
  $('tbSkip').onclick=()=>{TB=null;RENDER.teach();};$('tbText').oninput=e=>TB.text=e.target.value;$('tbDone').onclick=()=>{if(TB.text.trim().length<20){toast('Give it at least a couple of sentences.');return;}TB.stage='grade';RENDER.teach();};return;}
 const n=Object.values(TB.ticks).filter(Boolean).length;
 el.innerHTML='<div class="view-head"><div class="ph"><span class="eyebrow">Grade yourself</span><h1>How did you do?</h1></div></div><div class="card" style="display:flex;flex-direction:column;gap:8px"><span class="eyebrow">You wrote</span><p class="tb-echo">'+esc(TB.text)+'</p></div><div class="card" style="display:flex;flex-direction:column;gap:10px"><span class="eyebrow">Key points · tick the ones you covered</span>'+t.rub.map((r,i)=>'<label class="tb-rub'+(TB.ticks[i]?' on':'')+'"><input type="checkbox" data-i="'+i+'"'+(TB.ticks[i]?' checked':'')+'><span>'+esc(r)+'</span></label>').join('')+'<div class="btnrow" style="justify-content:space-between"><span class="num" style="font-size:18px">'+n+' / '+t.rub.length+'</span><button class="btn primary" id="tbSave">Save</button></div></div>';
 el.querySelectorAll('.tb-rub input').forEach(cb=>cb.onchange=()=>{TB.ticks[cb.dataset.i]=cb.checked;RENDER.teach();});
 $('tbSave').onclick=()=>{const score=n/t.rub.length;const prev=S.teach[t.c]||{};const box=score>=.75?(prev.box||0)+1:0;const days=[1,3,7,14,30,60][Math.min(5,box)];S.teach[t.c]={box,due:Date.now()+days*864e5,last:Math.round(score*100)};addXP(Math.round(score*20));touchDay();save();toast(score>=.75?'Solid explanation. Back in '+days+' days.':'Gaps found. It comes back tomorrow.',score>=.75?'good':'');TB=null;
  if(ROUND&&ROUND.legs[ROUND.i]&&ROUND.legs[ROUND.i].t==='teach')roundLegDone();else RENDER.teach();};};

/* ================= GAS SENSE (estimate before you calculate) ================= */
let ES=null,ES_N=0;
function estNew(){const k=pick(['ph','winters','hplus','agc','aa','ph']);let q;
 if(k==='ph'){const h=Math.round(rnd(6,40)),p=Math.round(rnd(18,85));const a=phFrom(h,p);if(a<6.9||a>7.7)return estNew();q={k,text:'HCO₃⁻ <b>'+h+'</b> mmol/L, PCO₂ <b>'+P(p)+' '+PU()+'</b>.',ask:'Estimate the pH',unit:'',min:6.9,max:7.7,step:0.01,tol:0.04,ans:a,fmt:x=>x.toFixed(2),work:'Ratio '+h+' ÷ (0.03 × '+p+') = '+(h/(0.03*p)).toFixed(1)+' (normal 20). pH = 6.1 + log('+(h/(0.03*p)).toFixed(1)+') = '+a.toFixed(2)+'. Henderson check: [H⁺] = 24 × '+p+' ÷ '+h+' = '+Math.round(24*p/h)+' nmol/L.'};}
 else if(k==='winters'){const h=Math.round(rnd(5,21));const a=1.5*h+8;q={k,text:'Metabolic acidosis with HCO₃⁻ <b>'+h+'</b> mmol/L.',ask:'Estimate the expected PCO₂ (mmHg)',unit:' mmHg',min:10,max:50,step:1,tol:3,ans:a,fmt:x=>String(Math.round(x)),work:'Winter\'s: 1.5 × '+h+' + 8 = '+r1(a)+' ± 2. Shortcut: HCO₃⁻ + 15 = '+(h+15)+' (fine for HCO₃⁻ 10–18).'};}
 else if(k==='hplus'){const ph=r2(rnd(7.0,7.6));const a=Math.pow(10,9-ph);q={k,text:'pH <b>'+ph.toFixed(2)+'</b>.',ask:'Estimate [H⁺] (nmol/L)',unit:' nmol/L',min:20,max:110,step:1,tol:5,ans:a,fmt:x=>String(Math.round(x)),work:'10^(9 − '+ph.toFixed(2)+') = '+Math.round(a)+' nmol/L.'+(ph>=7.2&&ph<=7.5?' The 80 rule: 80 − '+Math.round((ph-7)*100)+' = '+(80-Math.round((ph-7)*100))+'.':' Outside 7.20–7.50 the 80 rule drifts; remember 7.10 ≈ 80, 7.00 ≈ 100.')};}
 else if(k==='agc'){const na=Math.round(rnd(132,146)),hc=Math.round(rnd(8,24)),cl=Math.round(na-hc-rnd(6,24)),alb=Math.round(rnd(18,42));const ag=na-cl-hc,a=ag+0.25*(40-alb);q={k,text:'Na <b>'+na+'</b>, Cl <b>'+cl+'</b>, HCO₃⁻ <b>'+hc+'</b>, albumin <b>'+alb+'</b> g/L.',ask:'Estimate the albumin-corrected anion gap',unit:'',min:0,max:40,step:1,tol:2,ans:a,fmt:x=>String(Math.round(x)),work:'AG = '+na+' − ('+cl+' + '+hc+') = '+ag+'. Correction + 0.25 × (40 − '+alb+') = '+(0.25*(40-alb)>=0?'+':'')+r1(0.25*(40-alb))+' → '+r1(a)+'.'};}
 else{const pc=Math.round(rnd(26,70)),age=Math.round(rnd(25,80)),pa=(S.patm||760);const PA=0.21*(pa-47)-pc/0.8;const po=Math.round(PA-rnd(2,45));const a=PA-po;q={k,text:'Room air'+(pa!==760?' at '+pa+' mmHg':'')+': PaCO₂ <b>'+pc+'</b>, PaO₂ <b>'+po+'</b>, age <b>'+age+'</b>.',ask:'Estimate the A–a gradient (mmHg)',unit:' mmHg',min:0,max:60,step:1,tol:5,ans:a,fmt:x=>String(Math.round(x)),work:'PAO₂ = 0.21 × ('+pa+' − 47) − '+pc+' ÷ 0.8 = '+Math.round(PA)+'. A–a = '+Math.round(PA)+' − '+po+' = '+Math.round(a)+'. Expected ≤ '+Math.round(age/4+4)+' for age '+age+' (upper limit with tolerance '+Math.round(age/4+9)+'): '+(a>age/4+9?'raised.':'normal.')};}
 ES={q,v:null,shown:false};}
RENDER.est=function(){const el=$('v-est');if(!ES)estNew();const q=ES.q;const v=ES.v==null?(q.min+q.max)/2:ES.v;S.est=S.est||{n:0,c:0};
 const pct=x=>Math.max(0,Math.min(100,(x-q.min)/(q.max-q.min)*100));
 el.innerHTML='<div class="view-head"><div class="ph"><span class="eyebrow">Gas sense · '+S.est.n+' done · '+(S.est.n?Math.round(S.est.c/S.est.n*100):0)+'% close</span><h1>Estimate first</h1><p>Guess on the slider, then see the working. Number sense catches calculation slips at the bedside.</p></div></div>'+
 '<div class="card" style="display:flex;flex-direction:column;gap:14px"><p class="headline">'+q.text+'</p><p class="ask">'+q.ask+'</p><div class="ctrl"><label for="esIn"><span>Your guess</span><output id="esOut">'+q.fmt(v)+q.unit+'</output></label><input type="range" id="esIn" min="'+q.min+'" max="'+q.max+'" step="'+q.step+'" value="'+v+'"'+(ES.shown?' disabled':'')+'></div>'+
 '<div><div class="est-track">'+(ES.shown?'<span class="est-band" style="left:'+pct(q.ans-q.tol)+'%;width:'+(pct(q.ans+q.tol)-pct(q.ans-q.tol))+'%"></span>':'')+'<i class="est-you" style="left:'+pct(v)+'%"></i>'+(ES.shown?'<i class="est-ans" style="left:'+pct(q.ans)+'%"></i>':'')+'</div><div class="est-lab"><span>'+q.fmt(q.min)+'</span><span>'+q.fmt(q.max)+'</span></div></div>'+
 (ES.shown?'<div class="fb '+(ES.close?'ok':'no')+'"><div class="verdict"><i>'+(ES.close?'✓':'✗')+'</i>'+(ES.close?'Close enough.':'Off by '+q.fmt(Math.abs(v-q.ans)).replace(/^0\./,'0.')+'.')+' Answer: '+q.fmt(q.ans)+q.unit+'</div><p>'+q.work+'</p></div><div class="btnrow">'+(ROUND&&ROUND.legs[ROUND.i]&&ROUND.legs[ROUND.i].t==='est'&&ES_N>=3?legBtn('est'):'<button class="btn primary" id="esNext">Next →</button>')+'</div>':'<div class="btnrow"><button class="btn primary" id="esLock">Lock it in</button><span class="note">Within ± '+q.fmt(q.tol)+q.unit+' counts as close.</span></div>')+'</div>';
 const inp=$('esIn');if(inp&&!ES.shown)inp.oninput=e=>{ES.v=+e.target.value;$('esOut').textContent=q.fmt(ES.v)+q.unit;el.querySelector('.est-you').style.left=pct(ES.v)+'%';};
 if($('esLock'))$('esLock').onclick=()=>{ES.v=v;ES.shown=true;ES.close=Math.abs(v-q.ans)<=q.tol+1e-9;S.est.n++;ES_N++;if(ES.close){S.est.c++;addXP(6);}touchDay();save();RENDER.est();};
 if($('esNext'))$('esNext').onclick=()=>{estNew();RENDER.est();};};

