const FLASH=(()=>{const out=[];L.forEach(l=>(l.keys||[]).forEach((k,i)=>out.push({id:l.id+'-'+i,f:k[0],b:k[1],src:l.t,l:l.id})));
 [['Winter\'s formula','PCO₂ = 1.5 × HCO₃⁻ + 8 ± 2'],['Metabolic alkalosis compensation','PCO₂ = 0.7 × HCO₃⁻ + 20 ± 5'],['Respiratory acidosis: HCO₃⁻ per 10 mmHg','+1 acute · +4 chronic'],['Respiratory alkalosis: HCO₃⁻ per 10 mmHg','−2 acute · −5 chronic'],['Anion gap','Na − (Cl + HCO₃⁻)'],['Δ ratio','(AG − 12) ÷ (24 − HCO₃⁻)'],['Alveolar gas equation','PAO₂ = FiO₂ × (P_atm − 47) − PaCO₂ ÷ 0.8'],['Osmolar gap','measured − (2Na + glucose + urea)']].forEach((x,i)=>out.push({id:'rule-'+i,f:x[0],b:x[1],src:'Core rules',l:'comp'}));return out;})();
let FL=null;
function flashDeck(){const now=Date.now();S.flash=S.flash||{};const due=FLASH.filter(c=>S.flash[c.id]&&S.flash[c.id].due<=now);const fresh=FLASH.filter(c=>!S.flash[c.id]);return shuffle(due).concat(shuffle(fresh)).slice(0,20);}
RENDER.flash=function(){const el=$('v-flash');if(!FL||FL.i>=FL.deck.length&&!FL.done){FL={deck:flashDeck(),i:0,flipped:false,got:0,done:false,swipes:FL?FL.swipes:0};}
 const c=FL.deck[FL.i];
 if(!c){el.innerHTML='<div class="view-head"><div class="ph"><span class="eyebrow">Number flash</span><h1>'+(FL.deck.length?'Deck done':'Nothing due')+'</h1></div></div><div class="card" style="display:flex;flex-direction:column;gap:10px"><p>'+(FL.deck.length?FL.got+' of '+FL.deck.length+' known.':'All '+FLASH.length+' cards are scheduled for later.')+' Cards you knew come back after 3, 7, 16 and 35 days; misses come back tomorrow.</p><div class="btnrow"><button class="btn primary" id="flAgain">Another deck</button><button class="btn" data-go="practice">Practice</button></div></div>';$('flAgain').onclick=()=>{FL=null;RENDER.flash();};return;}
 const known=Object.values(S.flash||{}).filter(x=>x.box>=2).length;
 el.innerHTML='<div class="view-head"><div class="ph"><span class="eyebrow">Number flash · '+(FL.i+1)+'/'+FL.deck.length+' · '+known+' of '+FLASH.length+' known</span><h1>Recall the number</h1></div></div><div class="flashwrap"><div class="flashcard" id="flCard" tabindex="0" role="button" aria-label="Flash card, tap to flip"><small>'+esc(c.src)+'</small><div class="fq">'+esc(c.f)+'</div>'+(FL.flipped?'<div class="fa">'+esc(c.b)+'</div>':'<small>Tap to show</small>')+'</div>'+(FL.flipped?'<div class="btnrow"><button class="btn" id="flNo">← Again</button><button class="btn primary" id="flYes">Got it →</button></div>':'<div class="btnrow"><button class="btn primary" id="flFlip">Show</button></div>')+((FL.swipes||0)<5?'<p class="note">Swipe the card: right if you knew it, left if not. Arrow keys work too.</p>':'')+'</div>';
 const flip=()=>{FL.flipped=true;RENDER.flash();};$('flCard').onclick=()=>{if(!FL.flipped)flip();};if($('flFlip'))$('flFlip').onclick=flip;
 if($('flYes'))$('flYes').onclick=()=>flashRate(true);if($('flNo'))$('flNo').onclick=()=>flashRate(false);};
function flashRate(ok){const c=FL.deck[FL.i];if(!c)return;const s=S.flash[c.id]||{box:0};s.box=ok?Math.min(4,(s.box||0)+1):0;s.due=Date.now()+[1,3,7,16,35][s.box]*864e5;S.flash[c.id]=s;if(ok){FL.got++;addXP(1);}touchDay();save();FL.i++;FL.flipped=false;if(FL.i>=FL.deck.length)FL.done=true;RENDER.flash();}
document.addEventListener('keydown',e=>{if(VIEW!=='flash'||!FL||e.target.matches('input,textarea,select'))return;if(e.key===' '||e.key==='Enter'){if(!FL.flipped){e.preventDefault();FL.flipped=true;RENDER.flash();}}else if(e.key==='ArrowRight'&&FL.flipped)flashRate(true);else if(e.key==='ArrowLeft'&&FL.flipped)flashRate(false);});
document.addEventListener('keydown',e=>{if(VIEW!=='scen'||!SC||e.target.matches('input,textarea,select'))return;const n=parseInt(e.key,10);if(n>=1&&n<=4&&SC.sc.steps[SC.i]){const o=scOrd();if(o[n-1]!=null)scAnswer(o[n-1]);}else if(e.key==='Enter'&&$('scNext'))$('scNext').click();});

